import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem98 nao garante bateria ou autentica fragrancia e preserva operacao',()=>{for(const [id,titulo] of [['mlMLB4443112343','Fone de Ouvido Gamer In-ear Vellon TWS Bluetooth 5.0, com Microfone e Estojo de Carregamento'],['mlMLB4474977007','Salvo Maison Alhambra 100ml Eua De Parfum Perfume Original']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/conexão estável|6 h garantidas|cruelty.free certificado|autêntico/i);if(id==='mlMLB4474977007')assert.doesNotMatch(x.titulo,/Eua|Original/);}});
